/// command-palette: Commands, groups and shortcut hints
private struct CommandPaletteExample0: View {
    @State private var isOpen = PreviewMode.presented ? true : false
    @State private var query = ""
    @State private var lastCommand: String?

    private let commands = [
        MonarchSearchResultGroup(
            "Actions",
            id: "actions",
            results: [
                MonarchSearchResult("Create task", id: "new", systemImage: "plus", meta: "C", tone: .neutral),
                MonarchSearchResult("Rename", id: "rename", systemImage: "pencil", meta: "F2", tone: .neutral),
                MonarchSearchResult("Archive", id: "archive", systemImage: "trash", tone: .danger),
            ]
        ),
        MonarchSearchResultGroup(
            "Go to",
            id: "go-to",
            results: [
                MonarchSearchResult("Board", id: "board", systemImage: "rectangle.split.3x1", meta: "G B", tone: .neutral),
                MonarchSearchResult("My tasks", id: "list", systemImage: "list.bullet", meta: "G M", tone: .neutral),
                MonarchSearchResult("Settings", id: "settings", snippet: "Workspace", meta: "⌘,", tone: .neutral),
            ]
        ),
    ]

    private var matches: [MonarchSearchResultGroup] {
        guard !query.isEmpty else { return commands }
        return commands.map { group in
            MonarchSearchResultGroup(
                group.title,
                id: group.id,
                results: group.results.filter { $0.title.localizedCaseInsensitiveContains(query) }
            )
        }
    }

    var body: some View {
        VStack(alignment: .leading) {
            MonarchButton("Search commands", systemImage: "magnifyingglass") { isOpen = true }
                .keyboardShortcut("k", modifiers: .command)
                .sheet(isPresented: $isOpen) {
                    NavigationStack {
                        MonarchSearchResults(groups: matches, query: query) { command, _ in
                            lastCommand = command.title
                            isOpen = false
                        }
                        .searchable(text: $query, prompt: "Type a command or search")
                        .navigationTitle("Command palette")
                        #if os(iOS)
                        .navigationBarTitleDisplayMode(.inline)
