/// date-range-picker: Report period with presets
private struct DateRangePickerExample0: View {
    @State private var period: ClosedRange<Date>? = Date(timeIntervalSince1970: 1_791_244_800)...Date(timeIntervalSince1970: 1_793_750_400)
    private let today = Date(timeIntervalSince1970: 1_793_750_400)
    private static let iso: DateFormatter = {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd"
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(identifier: "UTC")
        return formatter
    }()

    var body: some View {
        MonarchDateRangePicker(
            "Report period",
            selection: $period,
            helper: (period.map { "\(Self.iso.string(from: $0.lowerBound)) to \(Self.iso.string(from: $0.upperBound))" } ?? "No period") + "; at most 366 days.",
            maximumDate: today,
            maximumDays: 366,
            presets: [
                .lastDays(7, label: "Last 7 days"),
                .lastDays(30, label: "Last 30 days"),
                .lastDays(90, label: "Last 90 days"),
                .month(0, label: "This month"),
                .month(-1, label: "Last month"),
            ],
            today: today
        )
        .environment(\.locale, Locale(identifier: "en-GB"))
        .environment(\.timeZone, TimeZone(identifier: "UTC") ?? .gmt)
    }
}

