        .padding(theme.spacing.space4)
        .frame(minHeight: theme.spacing.space24)
    }
}

/// query-builder: Nested AND / OR
private struct QueryBuilderExample0: View {
    @State private var query = MonarchQueryGroup(
        id: "root",
        combinator: .and,
        rules: [
            MonarchCondition(id: "r1", field: "status", operator: Self.queryOperator("eq"), value: .option("open")),
        ],
        groups: [
            MonarchQueryGroup(
                id: "g1",
                combinator: .or,
                rules: [
                    MonarchCondition(id: "r2", field: "amount", operator: Self.queryOperator("gte"), value: .number(500)),
                    MonarchCondition(id: "r3", field: "flagged", operator: Self.queryOperator("is_true")),
                ]
            ),
        ]
    )
    private let fields = [
        MonarchConditionField(id: "status", label: "Status", kind: .select([
            MonarchComboboxOption(id: "open", label: "Open"),
            MonarchComboboxOption(id: "pending", label: "Pending"),
            MonarchComboboxOption(id: "closed", label: "Closed"),
        ])),
        MonarchConditionField(id: "title", label: "Title", kind: .text),
        MonarchConditionField(id: "amount", label: "Amount", kind: .number, prompt: "Amount"),
        MonarchConditionField(id: "created", label: "Created", kind: .date),
        MonarchConditionField(id: "flagged", label: "Flagged", kind: .boolean),
    ]
    // The web operator names, as Monarch operators.
    private static func queryOperator(_ web: String) -> MonarchConditionOperator {
        switch web {
        case "gte": .atLeast
        case "is_true": .isTrue
        default: .equals
        }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            MonarchQueryBuilder(query: $query, fields: fields)
            Text("Sample record (open, amount 120, flagged) " + (query.matches(["status": .option("open"), "amount": .number(120), "flagged": .boolean(true)]) ? "matches" : "does not match") + ".")
                .monarchTextStyle(.body)
        }
    }
}

