/// quick-switcher: Jump to a channel or person
private struct QuickSwitcherExample0: View {
    @State private var isOpen = PreviewMode.presented ? true : false
    @State private var query = ""
    @State private var current = "#general"

    private static let places = [
        MonarchSearchResultGroup("Channels", id: "channels", results: [
            MonarchSearchResult("#general", id: "c-general", systemImage: "tray", tone: .neutral),
            MonarchSearchResult("#design-review", id: "c-design", systemImage: "tray", tone: .neutral),
            MonarchSearchResult("#launch-plan", id: "c-launch", systemImage: "tray", tone: .neutral),
        ]),
        MonarchSearchResultGroup("People", id: "people", results: [
            MonarchSearchResult("Ana Silva", id: "p-ana", snippet: "ana@example.com", systemImage: "person.2", tone: .neutral),
            MonarchSearchResult("Kofi Mensah", id: "p-kofi", snippet: "kofi@example.com", systemImage: "person.2", tone: .neutral),
        ]),
    ]
    private let recent = Array(Self.places[0].results.prefix(2))

    /// Forgiving match: the query's letters in order, so "gnl" finds "#general".
    private func matches(_ text: String) -> Bool {
        var rest = Substring(text.lowercased())
        for letter in query.lowercased() where !letter.isWhitespace {
            guard let found = rest.firstIndex(of: letter) else { return false }
            rest = rest[rest.index(after: found)...]
        }
        return true
    }

    private var groups: [MonarchSearchResultGroup] {
        let term = query.trimmingCharacters(in: .whitespaces)
        guard !term.isEmpty else {
            return [MonarchSearchResultGroup("Recent", id: "recent", results: recent)] + Self.places
        }
        var groups = Self.places.map { group in
            MonarchSearchResultGroup(group.title, id: group.id, results: group.results.filter {
                matches($0.title) || ($0.snippet.map(matches) ?? false)
            })
        }
        if term.count >= 2 {
            groups.append(MonarchSearchResultGroup("Search", id: "search", results: [
                MonarchSearchResult("Search for \u{201C}\(term)\u{201D}", id: "search-all", systemImage: "magnifyingglass"),
            ]))
        }
        return groups
    }

    var body: some View {
        VStack(alignment: .leading) {
            MonarchButton("Jump to…", systemImage: "magnifyingglass") { isOpen = true }
                .keyboardShortcut("k", modifiers: .command)
                .sheet(
                    isPresented: $isOpen,
                    onDismiss: { query = "" },
                    content: {
                        NavigationStack {
                            MonarchSearchResults(groups: groups, query: query) { place, _ in
                                current = place.id == "search-all" ? "Search results" : place.title
                                isOpen = false
                            }
                            .searchable(text: $query, prompt: "Jump to…")
                            .navigationTitle("Jump to")
                            #if os(iOS)
                            .navigationBarTitleDisplayMode(.inline)
                            #endif
                            .toolbar {
                                ToolbarItem(placement: .cancellationAction) {
                                    Button("Close") { isOpen = false }
                                }
                            }
                        }
                    }
                )
            Text("Open: \(current)")
                .monarchTextStyle(.body)
        }
    }
}

